  --kerykeion-chart-color-zodiac-icon-5: var(--kerykeion-color-warning);
  --kerykeion-chart-color-zodiac-icon-6: var(--kerykeion-color-primary);
  --kerykeion-chart-color-zodiac-icon-7: var(--kerykeion-color-secondary);
